const btn=(label,kind='',extra='')=>`<button class="btn ${kind}" ${extra}>${label}</button>`;
const field=(label,type='text',placeholder='',extra='')=>`<label class="field"><span class="field-label">${label}</span><input class="input" type="${type}" placeholder="${placeholder}" ${extra}></label>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${text}</span>`;
const avatar=(initials='JL',kind='')=>`<span class="avatar ${kind}" aria-label="${initials}">${initials}</span>`;
const tableMarkup=(manage=false)=>`<div class="scroll-area" role="region" aria-label="Team members table" tabindex="0"><table class="table"><caption>Workspace members</caption><thead><tr>${manage?'<th><input type="checkbox" aria-label="Select all members" data-select-all></th>':''}<th>Name</th><th>Role</th><th>Status</th></tr></thead><tbody>${[['Olivia Rhye','OR','Product designer','Active'],['Phoenix Baker','PB','Developer','Active'],['Lana Steiner','LS','Product manager','Invited']].map(([name,i,role,status])=>`<tr>${manage?`<td><input type="checkbox" aria-label="Select ${name}" data-row-check></td>`:''}<td><div class="inline">${avatar(i)}<span>${name}</span></div></td><td>${role}</td><td>${badge(status,status==='Active'?'success':'warning')}</td></tr>`).join('')}</tbody></table></div>`;
const catalog=[];
function add(category,name,description,html,note='Use a clear label, keep keyboard focus visible, and verify the component in context.'){catalog.push({category,name,description,html,note,id:name.toLowerCase().replace(/[^a-z0-9]+/g,'-')})}
add('actions','Buttons','Clear actions, from primary decisions to subtle controls.',`<div class="cluster">${btn('Continue '+icon('arrow'))}${btn('Secondary','secondary')}${btn('Tertiary','tertiary')}${btn('Ghost','ghost')}${btn('Delete','danger','data-confirm')}${btn(icon('plus'),'icon-btn','aria-label="Add item" data-toast="Item added"')}</div>`);
add('actions','Button sizes','Small, medium, and large; each retains a 44px touch target.',`<div class="cluster">${btn('Small','size-sm')}${btn('Medium')}${btn('Large','size-lg')}</div>`);
add('actions','Button states','Loading, disabled, and interactive states.',`<div class="cluster">${btn('Default','','data-toast="Action completed"')}${btn('<span class="spinner" aria-hidden="true"></span> Loading','','disabled aria-busy="true"')}${btn('Disabled','','disabled')}${btn('Save changes','secondary','data-loading')}</div>`,'Tab to focus. Hover and press a button for its CSS states. Disabled controls cannot be activated. Loading controls announce busy state.');
add('actions','Split button','A main action with related options.',`<div class="inline gap-2">${btn('Create project','','data-modal="project"')}<div class="popover-wrap">${btn(icon('down'),'icon-btn secondary','aria-label="More project actions" aria-expanded="false" data-popover')}<div class="popover" hidden><button data-toast="Template selected">Use template</button><button data-toast="Blank project selected">Start blank</button></div></div></div>`);
add('actions','Button group','Related actions arranged in a flexible group.',`<div class="button-group">${btn('Day','tertiary','data-choice aria-pressed="true"')}${btn('Week','secondary','data-choice aria-pressed="false"')}${btn('Month','secondary','data-choice aria-pressed="false"')}</div>`);
add('actions','Floating action button','A compact creation action.',btn(icon('plus')+' New item','fab','data-modal="project"'));
add('forms','Text input','Standard, required, optional, and disabled fields.',`<div class="stack">${field('Full name *','text','Alex Morgan','required autocomplete="name"')}${field('Company (optional)','text','Studio North')}${field('Workspace','text','Forma team','disabled')}<span class="helper">Use the name you share with your team.</span></div>`);
add('forms','Search input','Search with an embedded leading icon.',`<label class="field"><span class="field-label">Search projects</span><div class="input-wrap">${icon('search')}<input class="input" type="search" placeholder="Search projects…" data-demo-search></div><span class="helper" data-search-status>Try “Website” or “Mobile”.</span></label><ul class="list" data-search-list><li>Website redesign</li><li>Mobile application</li><li>Brand guidelines</li></ul>`);
add('forms','Password input','A password field with an accessible visibility toggle.',`<label class="field"><span class="field-label">Password</span><span class="input-wrap"><input class="input" type="password" placeholder="Enter your password" autocomplete="new-password" minlength="8">${btn(icon('eye'),'ghost icon-btn reveal','type="button" aria-label="Show password" aria-pressed="false" data-reveal')}</span><span class="helper">Use at least 8 characters.</span></label>`);
add('forms','Textarea','Multi-line content with a resize handle.',`<label class="field"><span class="field-label">Project description</span><textarea rows="3" placeholder="What are you working on?" maxlength="500" data-counter></textarea><span class="helper" data-count>0 / 500 characters</span></label>`);
add('forms','Select','Native single selection with keyboard support.',`<label class="field"><span class="field-label">Team role</span><select><option>Designer</option><option>Developer</option><option>Product manager</option></select></label>`);
add('forms','Multi-select','Native multiple selection for compact lists.',`<label class="field"><span class="field-label">Skills</span><select multiple size="3"><option>Interface design</option><option>Prototyping</option><option>Frontend development</option></select><span class="helper">Use Ctrl / Command to select multiple options.</span></label>`);
add('forms','Combobox','Searchable native suggestions; custom values are accepted.',`<label class="field"><span class="field-label">Country</span><input class="input" list="countries-__ID__" placeholder="Type a country"><datalist id="countries-__ID__"><option>Bangladesh</option><option>United Kingdom</option><option>United States</option><option>Canada</option></datalist></label>`);
add('forms','Checkbox','Multiple independent options.',`<div class="stack gap-2"><label class="check"><input type="checkbox" checked> Email notifications</label><label class="check"><input type="checkbox"> Product updates</label><label class="check"><input type="checkbox" disabled> Admin-only announcements</label></div>`);
add('forms','Radio button','One choice from a related set.',`<fieldset><legend class="small">Billing frequency</legend><label class="check"><input type="radio" name="billing-__ID__" checked> Monthly</label><label class="check"><input type="radio" name="billing-__ID__"> Annually — save 20%</label></fieldset>`);
add('forms','Toggle switch','Immediately enable or disable a preference.',`<div class="stack gap-2"><label class="check"><input type="checkbox" class="switch" role="switch" checked> Push notifications</label><label class="check"><input type="checkbox" class="switch" role="switch"> Weekly digest</label><label class="check"><input type="checkbox" class="switch" role="switch" disabled> Managed by administrator</label></div>`);
add('forms','Slider','Choose a value within a range.',`<label class="field"><span class="split"><span>Volume</span><output>60%</output></span><input type="range" min="0" max="100" value="60" data-range></label>`);
add('forms','Date and time picker','Native date and time entry with platform calendar controls.',`<div class="stack">${field('Start date','date','','value="2026-09-07"')}${field('Start time','time','','value="09:00"')}</div>`,'Calendar appearance and keyboard behavior follow the browser and operating system. Store dates with an explicit application timezone.');
add('forms','File upload','Choose files locally and review the selected filenames.',`<label class="field upload">${icon('upload')}<strong>Choose a file</strong><span class="helper">Images, PDF, or documents</span><input type="file" accept="image/*,.pdf,.doc,.docx" data-file><span class="helper" data-file-status>No file selected</span></label>`,'This demo only displays selected filenames. No file is uploaded to a server.');
add('forms','OTP input','Six-digit entry with paste and arrow-key support.',`<fieldset><legend class="small">Verification code</legend><div class="otp">${Array.from({length:6},(_,i)=>`<input class="input" aria-label="Digit ${i+1} of 6" inputmode="numeric" pattern="[0-9]" maxlength="1" ${i===0?'autocomplete="one-time-code"':''}>`).join('')}</div></fieldset>`);
add('forms','Input group','Related fields and actions in one row.',`<label class="field"><span class="field-label">Your website</span><span class="inline gap-2"><span class="small muted">https://</span><input class="input" placeholder="example.com" aria-label="Website domain">${btn('Check','secondary','type="button" data-toast="Demo: domain check requested"')}</span></label>`);
add('forms','Validation','Clear error and success messages linked to inputs.',`<div class="stack"><label class="field"><span class="field-label">Email address *</span><input class="input" type="email" value="alex@" aria-invalid="true" aria-describedby="error-__ID__"><span id="error-__ID__" class="error">Enter a complete email address.</span></label><label class="field"><span class="field-label">Username</span><input class="input" value="alexmorgan" aria-describedby="success-__ID__"><span id="success-__ID__" class="success">✓ This username is available.</span></label></div>`);
add('navigation','App header','Workspace identity with primary navigation and an action.',`<header class="split"><strong>Workspace</strong><nav class="cluster" aria-label="Example top navigation"><a class="nav-item" href="#patterns-dashboard">Dashboard</a>${btn(icon('bell'),'secondary icon-btn','aria-label="Open notifications" data-modal="notifications"')}</nav></header>`);
add('navigation','Sidebar navigation','Vertical navigation with a selected state.',`<nav class="stack gap-2" aria-label="Example sidebar"><a class="nav-item" aria-current="page" href="#patterns-dashboard">${icon('grid')} Overview</a><a class="nav-item" href="#patterns-profile">${icon('user')} Profile</a><a class="nav-item" href="#patterns-settings">${icon('settings')} Settings</a></nav>`);
add('navigation','Bottom navigation','Compact destination navigation for mobile applications.',`<nav class="bottom-nav" aria-label="Example bottom navigation"><a class="nav-item" href="#patterns-dashboard" aria-current="page">${icon('grid')}Home</a><a class="nav-item" href="#patterns-search">${icon('search')}Search</a><a class="nav-item" href="#patterns-profile">${icon('user')}Profile</a></nav>`);
add('navigation','Tabs','Switch related panels with arrow keys, Home, and End.',`<div data-tabs><div class="tabs" role="tablist" aria-label="Project detail"><button role="tab" id="tab-a-__ID__" aria-controls="panel-a-__ID__" aria-selected="true">Overview</button><button role="tab" id="tab-b-__ID__" aria-controls="panel-b-__ID__" aria-selected="false" tabindex="-1">Activity</button><button role="tab" id="tab-c-__ID__" aria-controls="panel-c-__ID__" aria-selected="false" tabindex="-1">Settings</button></div><div class="mt-4" role="tabpanel" id="panel-a-__ID__" aria-labelledby="tab-a-__ID__" tabindex="0"><p class="small">Your project is on track. 8 of 12 tasks are complete.</p></div><div class="mt-4" role="tabpanel" id="panel-b-__ID__" aria-labelledby="tab-b-__ID__" tabindex="0" hidden><p class="small">Olivia updated the design files 2 hours ago.</p></div><div class="mt-4" role="tabpanel" id="panel-c-__ID__" aria-labelledby="tab-c-__ID__" tabindex="0" hidden><label class="check"><input class="switch" role="switch" type="checkbox" checked> Project notifications</label></div></div>`);
add('navigation','Segmented control','Choose a display mode.',`<div class="segmented" role="group" aria-label="Display mode">${['List','Grid','Board'].map((x,i)=>`<button data-choice aria-pressed="${i===0}" ${i===0?'class="selected"':''}>${x}</button>`).join('')}</div><p class="small mt-4" data-choice-output>List view selected.</p>`);
add('navigation','Breadcrumb','Show the current location in a hierarchy.',`<nav class="breadcrumb" aria-label="Breadcrumb"><a href="#overview">Home</a><span aria-hidden="true">/</span><a href="#components-actions">Components</a><span aria-hidden="true">/</span><span aria-current="page">Navigation</span></nav>`);
add('navigation','Pagination','Move through pages of results.',`<div data-pagination><nav class="cluster" aria-label="Pagination">${btn('Previous','secondary','data-page="prev" disabled')}${[1,2,3].map(n=>btn(n,n===1?'tertiary':'ghost',`data-page="${n}" ${n===1?'aria-current="page"':''}`)).join('')}${btn('Next','secondary','data-page="next"')}</nav><p class="small mt-4" data-page-output>Page 1 of 3 · Items 1–10</p></div>`);
add('navigation','Stepper','Communicate progress through a multi-step task.',`<div class="stepper" aria-label="Setup progress"><span class="current" aria-current="step">Account</span><span>Workspace</span><span>Invite team</span></div>`);
add('navigation','Dropdown menu','Related actions in a dismissible panel.',`<div class="popover-wrap">${btn('Project actions '+icon('down'),'secondary','data-popover aria-expanded="false"')}<div class="popover" hidden><button data-toast="Project duplicated">Duplicate</button><button data-toast="Project archived">Archive</button><button data-confirm>Delete project</button></div></div>`,'Tab through the actions; Escape and clicking outside close the panel and restore focus.');
add('navigation','Command menu','Quickly find components and documentation.',btn(icon('search')+' Search documentation','secondary','data-command'));
add('data','Avatar and avatar group','Initials represent team members without external images.',`<div class="cluster">${avatar('OR')}${avatar('PB','large alt')}<div class="avatar-group" aria-label="3 team members">${avatar('OR')}${avatar('PB','alt')}${avatar('LS','green')}</div></div>`);
add('data','Badges and status indicators','Text and color work together to communicate status.',`<div class="cluster">${badge('✓ Active','success')}${badge('Pending','warning')}${badge('Failed','error')}${badge('Information','info')}${badge('New','brand')}${badge('Draft')}</div>`);
add('data','Tags and chips','Classify content and toggle filters.',`<div class="cluster"><span class="tag">Design</span><span class="tag">Development</span><button class="chip" aria-pressed="true" data-chip>All projects</button><button class="chip" aria-pressed="false" data-chip>Favorites</button></div>`);
add('data','Tooltip','Short supplemental help on hover and keyboard focus.',`<span class="tooltip-wrap">${btn(icon('info'),'secondary icon-btn','aria-label="More about workspace access" aria-describedby="tooltip-__ID__"')}<span class="tooltip" role="tooltip" id="tooltip-__ID__">Only your team can view this.</span></span>`);
add('data','Card','A flexible content container with optional actions.',`<article class="card stack"><span class="hug">${badge('In progress','brand')}</span><h3>Website redesign</h3><p>A shared space for the next chapter of your product.</p><div class="split"><div class="avatar-group">${avatar('OR')}${avatar('PB','alt')}</div>${btn('Open project','secondary','data-modal="project"')}</div></article>`);
add('data','Stat card','A key metric with a contextual comparison.',`<article class="card stack gap-2"><div class="split"><span class="stat-label">Total revenue</span>${icon('activity')}</div><strong class="stat-value">$24,680</strong><span class="success">↗ 12.8% <span class="muted">vs. last month</span></span></article>`);
add('data','Accordion','Expand and collapse supporting information.',`<div><details open><summary>Can I customize the theme?</summary><p>Yes. Update the semantic variables in themes.css to apply your brand consistently.</p></details><details><summary>Does it need a build step?</summary><p>No. Open index.html in your browser or serve the files with any static server.</p></details><details><summary>Can I use it commercially?</summary><p>Yes. The component source is available under the MIT license.</p></details></div>`);
add('data','List and description list','Structured text for activity and metadata.',`<ul class="list"><li class="split"><span>Design review</span>${badge('Today','brand')}</li><li class="split"><span>Team standup</span><span class="small muted">09:30 AM</span></li></ul><dl><dt>Owner</dt><dd>Olivia Rhye</dd><dt>Created</dt><dd>September 6, 2026</dd><dt>Visibility</dt><dd>Team only</dd></dl>`);
add('data','Table', 'Readable tabular data in a keyboard-scrollable region.',tableMarkup());
add('data','Data table','Select individual members or the complete visible set.',tableMarkup(true)+'<p class="small mt-4" data-selection-status>0 members selected</p>');
add('data','Timeline','A chronological sequence with explicit timestamps.',`<ol class="timeline"><li><strong>Project created</strong><p>September 2 · Olivia Rhye</p></li><li><strong>Design review completed</strong><p>September 4 · Product team</p></li><li><strong>Development started</strong><p>September 6 · Phoenix Baker</p></li></ol>`);
add('data','Progress','Linear and circular progress displays.',`<div class="stack"><label class="field">Upload progress — 68%<progress class="progress" value="68" max="100">68%</progress></label><div class="progress-circle" role="progressbar" aria-label="Setup completion" aria-valuenow="75" aria-valuemin="0" aria-valuemax="100">75%</div></div>`);
add('data','Skeleton loader','Reserve space while content loads.',`<div class="stack" role="status" aria-label="Loading content"><div class="skeleton block"></div><div class="skeleton"></div><div class="skeleton short"></div><span class="sr-only">Loading content…</span></div>`);
add('data','Empty state','Explain an empty view and provide the next action.',`<div class="empty">${icon('inbox')}<h3>No projects yet</h3><p>Create your first project to start collaborating.</p>${btn(icon('plus')+' Create project','','data-modal="project"')}</div>`);
add('data','Image placeholder','A neutral frame for missing or pending imagery.',`<div class="placeholder" role="img" aria-label="Image placeholder">${icon('file','icon-lg')}</div>`);
add('feedback','Alerts','Persistent feedback with a specific next step.',`<div class="stack"><div class="alert">${icon('info')}<p><strong>A new version is available.</strong><br>Refresh when you are ready.</p></div><div class="alert success">${icon('check')}<p>Your changes have been saved.</p></div><div class="alert warning">${icon('info')}<p>Your trial ends in 3 days.</p></div><div class="alert error">${icon('info')}<p>Upload failed. Please try again.</p></div></div>`);
add('feedback','Toast','Short feedback announced without moving focus.',`<div class="cluster">${btn('Show success','secondary','data-toast="Changes saved successfully"')}${btn('Show information','secondary','data-toast="Your export is being prepared"')}${btn('Show error','danger','data-toast="Demo error: unable to complete the request"')}</div>`);
add('feedback','Banner','A page-level announcement with a dismissal action.',`<div class="banner split"><span>Meet your updated workspace.</span>${btn(icon('close'),'ghost icon-btn','aria-label="Dismiss announcement" data-dismiss-banner')}</div>`);
add('feedback','Modal','A focused task using a native modal dialog.',btn('Create a project','','data-modal="project"'),'Uses native dialog focus containment, Escape dismissal, a visible close button, and focus restoration.');
add('feedback','Confirmation dialog','Confirm a destructive action with specific language.',btn('Delete project','danger','data-confirm'));
add('feedback','Drawer','A side panel for contextual information.',btn('Open notification drawer','secondary','data-modal="notifications"'));
add('feedback','Popover','Extra context anchored to its trigger.',`<div class="popover-wrap">${btn('Sharing details '+icon('info'),'secondary','data-popover aria-expanded="false"')}<div class="popover" hidden><p class="small">This project is shared with 3 members. Only workspace members have access.</p></div></div>`);
add('feedback','Loading spinner','A compact indeterminate loading indicator.',`<div class="inline" role="status"><span class="spinner" aria-hidden="true"></span><span class="small">Loading workspace…</span></div>`);
add('feedback','Success and error states','Explicit outcomes with a useful next action.',`<div class="stack"><div class="alert success">${icon('check')}<p><strong>Invitation sent</strong><br>Your teammate can now join the workspace.</p></div><div class="alert error">${icon('info')}<p><strong>Something went wrong</strong><br>Check your connection and try again.</p></div>${btn('Try again','secondary','data-toast="Demo retry completed"')}</div>`);
